        ∀ (ι : ℤ × ℤ), ∀ᵐ (z : ℝ × Breakdown.Space), ∑ i, Breakdown.modeGrad ι G z.1 z.2 (i, i) = 0

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
