∀ {k : ℕ} {W : ℝ → Breakdown.Space → Breakdown.Space} {act : Fin k → ℝ → Breakdown.Space → Breakdown.Space}
  (κ : Fin k → ℝ) {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space} (z : ℝ × Breakdown.Space),
  g z.1 z.2 + (G z.1 z.2) (W z.1 z.2) + (fderiv ℝ (W z.1) z.2) (v z.1 z.2) + ∑ i, κ i • act i z.1 z.2 =
    g z.1 z.2 - Breakdown.secondDerivTrace (H z.1 z.2) + (G z.1 z.2) (W z.1 z.2) + (fderiv ℝ (W z.1) z.2) (v z.1 z.2) +
        ∑ i, κ i • act i z.1 z.2 +
      Breakdown.secondDerivTrace (H z.1 z.2)

∀ {C : Type} {m : Breakdown.ModeWeights C} {P : ℝ} {b : Breakdown.FlowBounds C} {w : Breakdown.Space → ℝ}
