        Breakdown.IsWeakGradient (Breakdown.Coercive.ModeDerivative.Internal.columnFamily G l σ p)
          (Breakdown.Coercive.ModeDerivative.Internal.secondDerivFamily hRot H l σ p)

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
