∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {W v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    (∃ D, ∀ (σ : ℝ) (y : Breakdown.Space), ∀ j ≤ 2, ‖iteratedFDeriv ℝ j (W σ) y‖ ≤ D / (1 + ‖y‖) ^ (j + 1)) →
      (Breakdown.periodLIntegral fun σ y => ‖v σ y‖ ^ 2 / (1 + ‖y‖) ^ 2) < ⊤ →
        (Breakdown.periodLIntegral fun σ y => |Breakdown.stretchForm W v G σ y|) < ⊤

∀ {Γ₁ Γ₂ : Set Breakdown.Symmetry} {P : ℝ} {a b : ℝ → Breakdown.Space → Breakdown.Space}
  {A B : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {AA BB : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {ga gb : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ₁ P a A AA ga →
    Breakdown.IsPerturbation Γ₂ P b B BB gb →
      Breakdown.IsPerturbation ∅ P (fun σ y => a σ y - b σ y) (fun σ y => A σ y - B σ y) (fun σ y => AA σ y - BB σ y)
        fun σ y => ga σ y - gb σ y

